const LEVEL_CAP = 50;
function xpForLevel(level) {
  if (level <= 1) return 0;
  const clamped = Math.min(level, LEVEL_CAP);
  return 50 * (clamped - 1) * clamped;
}
function calculateLevelFromXp(xp) {
  if (!xp || xp <= 0) return 1;
  let level = 1;
  while (level < LEVEL_CAP && xp >= xpForLevel(level + 1)) {
    level++;
  }
  return level;
}
