    base.intervalDays = intervalDays;
    base.dueAt = now + intervalDays * DAY_MS;
    base.consecutiveCorrect = consecutive;
    base.distinctQuestionsCorrect = Array.from(distinctSet);
    base.isMastered = isMastered;
    base.lastAttemptAt = now;
